const LORE_TERMS={
  'Visione':{tip:'Helm, der Erinnerungsfragmente lesen kann. Erhalt in Kap. 2, Quest „Unerwartetes Geschenk“: Belohnung des Schritts „Untersuche das Innere des Wachturms“ (Mission „Erinnerungsfragment“) im Löwenmähne-Wachturm, zu dem die Mission „Wo das Licht hinführt“ führt.',sec:'secrets',tab:'fragments'},
  'Axiom Archive':{tip:'Abyss-Gebiet mit eigenem Abyss-Nexus, erreicht in Kap. 1 (Quest „Polar Opposites“); Alustin ist sein Hüter. Laut VULKK und consolepulse im Pfad der Vorsehung. 3. Stock = Hidden-Ending-Bücher (Aufzeichnungen aus dem Archiv). Laut VULKK sind Spirit Fähigkeiten dort blockiert — Macht des Axioms nutzen.',sec:'secrets',tab:'ending'},
  'Axiom Force':{tip:'Telekinese-Fähigkeit (Kap. 1 automatisch). Pflicht für das Archiv des Axioms 3. Stock.',sec:'skills'},
  'Run 108':{tip:'Deutung der Guides: Der gespielte Durchlauf ist Versuch Nr. 108. Die Aufzeichnungen aus dem Archiv im Archiv des Axioms enden mit Eintrag #107 („The next attempt will be our final chance“).',sec:'secrets',tab:'ending'},
  'White Crow':{tip:'Eines der vier Wesen, die das Gleichgewicht des Abyss wahren; existiert seit alter Zeit an Alustins Seite und hilft Kliff aus dem Verborgenen. Laut Archive Entry #2 verschlang Umbra ein Fragment von ihr (→ Hexe Marie).',sec:'witches'},
  'Memory Fragment':{tip:'Ortsgebundene Knowledge-Events (laut crimsondesert.th.gl 201, Stand 07.04.2026; seit 2.00.00 kamen weitere hinzu). Visione + Laterne aktivieren.',sec:'secrets',tab:'fragments'},
  'Memory Fragments':{tip:'Ortsgebundene Knowledge-Events (laut crimsondesert.th.gl 201, Stand 07.04.2026; seit 2.00.00 kamen weitere hinzu). Visione + Laterne aktivieren.',sec:'secrets',tab:'fragments'},
  'Abyss Cresset':{tip:'60 versteckte Abyss-Grenzsteine (= Geheime Orte; auf der Karte als „Mysteriöse Energie“). Je Cresset ein Abyss-Artefakt (Lernwährung für Fähigkeiten) + Schnellreisepunkt. Trophy "Pilgrim of Wonders".',sec:'secrets',tab:'cressets'},
  'Abyss Cressets':{tip:'60 versteckte Abyss-Grenzsteine (= Geheime Orte). Je Cresset ein Abyss-Artefakt (Lernwährung für Fähigkeiten) + Schnellreisepunkt.',sec:'secrets',tab:'cressets'},
  'Cressets':{tip:'60 versteckte Abyss-Grenzsteine (= Geheime Orte). Je Cresset ein Abyss-Artefakt (Lernwährung für Fähigkeiten) + Schnellreisepunkt.',sec:'secrets',tab:'cressets'},
  'Pilgrim of Wonders':{tip:'Trophy bei allen 60 Cressets.',sec:'secrets',tab:'cressets'},
  'Dark Fog Lantern':{tip:'Verbesserte Laterne aus der Alfonso-Quest „Transzendentes Bauwerk“ (Alfonso House, Hernand). Laut Spielbeschreibung durchdringt ihr Licht selbst dichtesten Nebel; laut dropreference hilft sie auch beim Aufspüren von Erinnerungsfragment, Hinweisen und versiegelten Abyss Artefakte.',sec:'secrets',tab:'tools'},
  'Hidden Ending':{tip:'Laut consolepulse kein alternatives Ende, sondern eine Lore-Auflösung: 6 Archive-Records-Bücher (42 Einträge) im 3. Stock des Archivs des Axioms, verfügbar nach Story-Abschluss inkl. Epilog und den 40 Pflicht-Abyss-Herausforderungen (inkl. Dimensionsrahmen).',sec:'secrets',tab:'ending'},
  'Path of Providence':{tip:'Abyss-Gebiet. Laut VGC beginnt dort am Abyss Nexus Ätherischer Pfad (nach Freischalten des Flugs) eine Kette von Abyss-Puzzle-Räumen: Wurzelende, Abgrund der Wahrheit, The Secret Garden, Tür der Rache, Garten der Wahrheit, Altar der Einsamkeit, Eiswiege — jeweils mit Abyss-Artefakt. Laut VULKK und consolepulse liegt auch das Archiv des Axioms im Pfad der Vorsehung.',sec:'locations'},
  'Path of Trials':{tip:'Abyss-Challenge („A pure white Abyss where everything is frozen“) im Abyss-Gebiet hinter der Spitze der klingenden Wahrheit (Priscus). Zusammen mit Äthersruh und Bitteres Paradies schaltet sie das Element Frost und damit Bitterer Mantel frei.',sec:'skills'},
  'Caliburn':{tip:'Gabriel Caliburn, Duke aus Demeniss. Archive Entry #72: „He appears to be an incarnation of Umbra“ — laut Archiv scheinbar eine Inkarnation Umbras (siehe Hidden Ending).',sec:'secrets',tab:'ending'},
  'Hexe Marie':{tip:'Boss Kap. 9. Lore (Archive Entry #2 und #18): der von Umbra verschlungene, abgespaltene Teil der Weißen Krähe; besessen von Kliff, will ihn zu ihrem Sohn machen.',sec:'bosses'},
  'Hollow Visage':{tip:'Hidden Weapon: ATK 30 (Refinement +10; Basiswert bei +0: 10) mit 3 Cores (Einsicht I, Sturmwind I, Zerstörung I; dropreference nennt statt Sturmwind I "Gale I", vermutlich derselbe Core). Morgenrothöhle hinter Wasserfall.',sec:'weapons'},
  'Survivor\'s Solitude':{tip:'Hidden Weapon: ATK 34 (Refinement +10; Basiswert bei +0: 12) mit 3 Cores (Sturmwind I, Einsicht I, Zerstörung I). Todesgriffhöhle hinter dem Wasserfall im Winterbergbecken (laut dropreference NW von Kharonso-See).',sec:'weapons'},
  'Vessel of Dark Pursuit':{tip:'Hidden Weapon: ATK 43 (Refinement +10; Basiswert bei +0: 16) + Wunde der Finsternis. Antumbras Schwert Boss im Sanktum der Absolution.',sec:'weapons'},
  'Sanctum of Absolution':{tip:'Sanktum-Boss Antumbra\'s Sword + Drop: Vessel of Dark Pursuit.',sec:'witches'},
  'Lord\'s Sword':{tip:'Schwert des Fürsten — Belohnung nach dem Kampf gegen Kailok, den Hornspalter (Kap. 2, Quest „Das Ende der Gier“, Mission „Von der Kante wiederhallender Jubel“, Schritt „Shakatus Belohnung“); questlog führt zusätzlich den Händler Grimrak. Windhieb ist bereits als Abyss-Ausrüstung eingesetzt (dazu Zerstörung I, Sturmwind I).',sec:'weapons'},
  'Wind Slash':{tip:'Abyss-Ausrüstung für Nahkampfwaffen: schickt nach bestimmten Aktionen eine Windklinge nach vorn. Vorgesockelt im Schwert des Fürsten, außerdem per Blaupause bei den Hexen herstellbar.',sec:'cores'},
  'Goyen':{tip:'Boss im Nest der Tapferkeit (Kap. 9, Unerschütterlicher Schritt). Archive Entries #45/#47/#99: früherer Schützling der Abyss-Wächter („Our painstaking creation“), nahm nach dem Verlust seiner Gefährten den Namen Goyen an. Fan-Deutung: ein Kliff aus einem früheren Durchlauf. Laut VULKK 107 Striche über seinem Bett (mit Laterne sichtbar).',sec:'secrets',tab:'ending'},
  'Antumbra\'s Sword':{tip:'Sanktum-Boss · Sanktum der Absolution · droppt Gefäß der Finsteren Jagd.',sec:'bosses'},
   'Alustin':{tip:'Alchemist der Burg Hernand, in Wahrheit eines der vier Wesen, die das Gleichgewicht des Abyss wahren (mit Weiße Krähe und Meister Du); Hüter des Archivs des Axioms.',sec:'npcs'},
   'Marni':{tip:'Herrscher von Delesyia und Erfinder der Visiones. Story (Kap. 11): H.A.L.L. imitiert ihn, der echte Marni hilft Kliff aus dem Verborgenen. Archive Entry #48 erwähnt ihn.',sec:'npcs'},
   'H.A.L.L.':{tip:'Von Marni geschaffene Intelligenz, vom Abyss verschlungen; imitiert Marni und beherrscht Delesyia. Fraktion mit Mechas, Schlachtschiff, Crushern und Orbian.',sec:'bestiary'},
   'Ancients':{tip:'Rätselhafte Magier der Urzeit; laut Legende vom Gott der Weisheit versiegelt, nachdem sie, vom Abyss berauscht, Zerstörung brachten. Die Walker (Stone-, Ice-, Mud-, Runewalker ...) sind Ancients, die ihren Körper verloren haben und deren Seele in Stein, Eis, Schlamm u. a. gebunden ist.',sec:'bosses'}
};
